--   quests[퀘스트 ID] = { lvl = 퀘스트 레벨, min = 수락 최소 레벨, sort = 분류(양수 지역 ID, 음수 퀘스트 분류),
--                        next = 이어지는 퀘스트(없으면 생략), races = 종족 비트 마스크 하위 32비트(제한 없으면 생략),
--                        obj = { {종류, 대상 ID, 개수}, ... } }
