--   givers[퀘스트 ID] = turnIns 와 같은 형식 (퀘스트를 주는 NPC·오브젝트)
--   eventSpots[퀘스트 ID] = { [목표 번호] = { 대륙, x, y } }   (도착·정찰 목표를 마친 곳)
